// The typed client generated by sync-engine (`bun run generate` writes
// generated/wire.ts). Every endpoint is a method on `api`, with its input and
// output types checked against the backend.
import { createHttpClient } from "@mit-sdg/sync-engine-http/client";
import type { BFSThisMessWireHttp } from "../generated/wire.ts";

const client = createHttpClient<BFSThisMessWireHttp>({
  baseUrl: new URL("/api", window.location.origin).toString(),
});

export const api = client.bfsthismess;

// ---------- Response types, derived from the wire so they never drift ----------

type Output<P extends keyof BFSThisMessWireHttp> = BFSThisMessWireHttp[P]["output"];
type RoadView = Output<"/bfsthismess/viewRoad">;

export type Constraints = RoadView["constraints"]["constraints"][number];
export type Plan = RoadView["paths"]["catalogs"][number]["paths"]["paths"][number]["plan"];
export type Ratings = Output<"/bfsthismess/viewRatings">["ratings"]["ratings"][number];
export type Schedule = Output<"/bfsthismess/viewSchedule">["schedule"]["schedule"][number];

// ---------- Errors ----------

// The client answers either the output or { error }. Turn the error case into
// an exception so callers can use try/catch and get the output type directly.
export class ApiError extends Error {}

export async function unwrap<R extends object>(
  pending: Promise<R>,
): Promise<Exclude<R, { error: unknown }>> {
  const result = await pending;
  if ("error" in result) throw new ApiError(String((result as { error: unknown }).error));
  return result as Exclude<R, { error: unknown }>;
}

export function message(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}
